/// Artwork for [category] at [tier], clamped to what exists.
String clubArtFor(String category, int tier) {
  final art = clubArtByCategory[category] ?? clubArtByCategory['TRAINING']!;
  final idx = (tier - 1).clamp(0, art.length - 1);
  return art[idx];
}
